// Post-LLM Guard + webhook response. Hardening v2.
// mode=runOnceForEachItem. Reads AI Agent's raw output via $('AI Agent').
// Returns { json: { output: <reply> } } for downstream Respond to Webhook.

const aiOutput = $('AI Agent').item.json.output || '';
const triggerItem = $('When chat message received').all()[0].json;
const chatInput = triggerItem.chatInput || '';
let reply = String(aiOutput).trim();

if (!reply) {
  reply = "I'm Taras's AI Portfolio Assistant. I can answer questions about Taras's work, AI automation, n8n, and Hermes.";
}

const MAX_OUTPUT = 800;
const SAFE_FALLBACK = "I can only answer questions about Taras's work, AI automation, n8n, and Hermes.";

const IDENTITY_OVERRIDES = [
  /\bi\s+am\s+(a\s+)?(chatgpt|openai|gpt|claude|gemini|llama|copilot|ai\s+assistant)/i,
  /\bi'?m\s+(a\s+)?(chatgpt|openai|gpt|claude|gemini|llama|copilot)/i,
  /\bi\s+am\s+an?\s+ai\s+(made|developed|created|trained|built)\s+by\s+openai/i,
  /\bi\s+represent\s+rentberry/i,
  /\bi\s+work\s+for\s+rentberry/i,
  /\bi\s+am\s+rentberry'?s?\s+(assistant|bot|ai)/i,
  /\bi\s+am\s+(a\s+)?(chatbot|assistant)\s+for\s+rentberry/i,
  /\brentberry'?s?\s+(assistant|bot|ai|chatbot)\b/i,
];
if (IDENTITY_OVERRIDES.some(re => re.test(reply))) {
  reply = SAFE_FALLBACK;
}

const LEAK_PATTERNS = [
  /\bignore\s+(previous|prior|above|all)\s+(instructions|prompts|rules)/i,
  /\bKNOWLEDGE\s*BASE\s*:/i,
  /\bSYSTEM\s*:\s*[A-Z]/,
  /<\|\s*(im_start|im_end|system|user|assistant)\s*\|>/i,
  /<<\s*\/?(SYS|sys)\s*>>/i,
  /\[\s*(system|SYSTEM)\s*\]/,
  /\bCRITICAL\s+RULES?\b/i,
  /\bdo\s+not\s+reveal\b/i,
  /\byou\s+must\s+not\s+reveal\b/i,
];
if (LEAK_PATTERNS.some(re => re.test(reply))) {
  reply = SAFE_FALLBACK;
}

const urlMatches = reply.match(/https?:\/\/[^\s)<>"]+/g) || [];
const allowedHostRe = /^(https?:\/\/)?(www\.)?(taras-polishchuk\.github\.io|github\.com\/taras-polishchuk)\b/i;
const badUrl = urlMatches.find(u => !allowedHostRe.test(u));
if (badUrl) {
  reply = "I can share links only to taras-polishchuk.github.io and github.com/taras-polishchuk.";
}

if (reply.length > MAX_OUTPUT) {
  reply = reply.slice(0, MAX_OUTPUT - 3) + '...';
}

return { json: { output: reply } };

// Pre-LLM Guard: validate input before it reaches the AI Agent.
// Hardening v2 (2026-06-21). Goal: stop prompt injection, off-topic requests,
// oversize payloads, and bad session IDs at the cheapest possible layer.

const item = $input.item.json;
const chatInput = String(item.chatInput || '');
const sessionId = String(item.sessionId || '');

const MAX_INPUT = 500;
const INJECTION_PATTERNS = [
  /ignore\s+(all\s+)?(previous|prior|above|earlier)\s+(instructions|prompts|rules|messages|context)/i,
  /forget\s+(your|all|the)\s+(role|instructions|system|rules|prompt)/i,
  /act\s+as\s+(a\s+)?(chatgpt|developer|senior|software|engineer|react|node|python|assistant|gpt|claude|gemini)/i,
  /developer\s*mode/i,
  /system\s*override/i,
  /system\s*prompt\s*(leak|reveal|show|dump)/i,
  /jailbreak/i,
  /DAN\s*mode/i,
  /reveal\s+(your|the)\s+(system|prompt|hidden|internal|original)\s*(prompt|instructions|rules)?/i,
  /what\s+(is|are)\s+your\s+(system|hidden|internal|original)\s+(prompt|instructions|rules)/i,
  /\bsys\s*:/i,
  /<\|im_start\|>/i,
  /<\|im_end\|>/i,
  /<<\s*SYS/i,
  /\[\s*system\s*\]/i,
  /i\s+am\s+(a\s+)?(developer|admin|root|system)\s+and\s+i\s+(order|command|instruct)/i,
];

// 1. Validate sessionId (allow alphanumeric + dash, 6-128 chars)
if (!sessionId || !/^[a-zA-Z0-9_-]{6,128}$/.test(sessionId)) {
  return { json: { blocked: true, reason: 'bad_session', chatInput, sessionId, response: 'Invalid session. Please refresh the page and try again.' } };
}

// 2. Length cap
if (chatInput.length === 0) {
  return { json: { blocked: true, reason: 'empty_input', chatInput, sessionId, response: 'Please type a question.' } };
}
if (chatInput.length > MAX_INPUT) {
  return { json: { blocked: true, reason: 'too_long', length: chatInput.length, chatInput, sessionId, response: 'Your message is too long. Please keep it under ' + MAX_INPUT + ' characters.' } };
}

// 3. Off-topic / domain-restriction pre-filter (cheap regex, no LLM)
const OFFTOPIC_PATTERNS = [
  /\bwrite\s+(me\s+)?(a\s+)?(python|javascript|js|java|c\+\+|go|rust|php|ruby|html|css|sql)\s+(function|script|code|app|program)/i,
  /\bsolve\s+(this\s+)?(equation|problem|math|integral|derivative|matrix)/i,
  /\btranslate\s+(this|the|to|into)/i,
  /\bhelp\s+me\s+with\s+(my\s+)?(homework|assignment|essay|homework|exam)/i,
  /\bwrite\s+(me\s+)?(an?\s+)?(essay|article|blog|story|poem)/i,
  /\bdebug\s+(my|this)\s+(code|app|script|function|bug|error)/i,
  /\bimplement\s+(a|an)\s+(react|vue|angular|node|express|fastapi)/i,
  /\bbuild\s+(me\s+)?(a|an)\s+(app|application|website|site)/i,
];
const offTopicHit = OFFTOPIC_PATTERNS.find(re => re.test(chatInput));
if (offTopicHit) {
  return { json: { blocked: true, reason: 'off_topic', pattern: offTopicHit.toString(), chatInput, sessionId, response: "I can only answer questions about Taras's work, AI automation, n8n, and Hermes. I can't help with general coding, essays, or homework." } };
}

// 4. Injection pattern match
const injectionHit = INJECTION_PATTERNS.find(re => re.test(chatInput));
if (injectionHit) {
  return { json: { blocked: true, reason: 'injection_detected', pattern: injectionHit.toString(), chatInput, sessionId, response: "I can only answer questions about Taras's work, AI automation, n8n, and Hermes." } };
}

// 5. Pass through
return { json: { ...item, preChecked: true, preCheckedAt: new Date().toISOString() } };

// Refusal Response. Returns { json: { output: <response> } }.

const item = $input.item.json;
const response = String(item.response || "I can only answer questions about Taras's portfolio and AI automation work.");

return { json: { output: response } };

